-- Demo data: generated by database/demo/generate_seed.py. Remove with database/demo/remove.sql.
-- Apply with: npm run demo:seed (removes any existing demo data first, all in one transaction).
DO $$
DECLARE b bigint;
u_arvind uuid := (SELECT p.user_id FROM bugflow.portals p WHERE p.type='admin' ORDER BY p.created_at LIMIT 1);
u_jenith uuid := (SELECT id FROM bugflow.users WHERE lower(name)='jenith' AND email NOT LIKE '%@demo.bugboard.test' AND deleted_at IS NULL ORDER BY created_at LIMIT 1);
u_stephen uuid := (SELECT id FROM bugflow.users WHERE lower(name)='stephen' AND email NOT LIKE '%@demo.bugboard.test' AND deleted_at IS NULL ORDER BY created_at LIMIT 1);
BEGIN
  IF u_arvind IS NULL THEN RAISE EXCEPTION 'Demo seed needs an existing member named arvind'; END IF;
  IF u_jenith IS NULL THEN RAISE EXCEPTION 'Demo seed needs an existing member named jenith'; END IF;
  IF u_stephen IS NULL THEN RAISE EXCEPTION 'Demo seed needs an existing member named stephen'; END IF;
END $$;
